  function toolButtons(site){const id=esc(key(site));return '<p class="station-meta">'+esc(equipmentLabel(site))+'</p><div class="station-tools"><button type="button" data-tool="estimate" data-site="'+id+'">Estimer coût et durée</button><button type="button" data-tool="favorite" data-site="'+id+'">'+(favorites.has(key(site))?'★ Retirer le favori':'☆ Ajouter aux favoris')+'</button><button type="button" data-tool="tarif" data-site="'+id+'">Ajouter / corriger le tarif</button><button type="button" data-tool="problem" data-site="'+id+'">Signaler un problème</button><a target="_blank" rel="noopener" href="https://github.com/sauverspl-tech/ProjetX-Recharge-Electrique/issues?q='+encodeURIComponent('is:issue "'+key(site)+'"')+'">Voir / confirmer les signalements ↗</a></div>';}
  const dialogIds=['estimate-dialog','contribution-dialog'];
