  function setStationPower(){if(!selectedToolSite)return;const rows=equipment[key(selectedToolSite)]||[],match=rows.filter(r=>r[0]===Number($('estimate-plug').value)&&r[1]>0);$('station-kw').value=match.length?Math.max(...match.map(r=>r[1])):'';$('estimate-result').hidden=true;}
