    if(site){const options=equipment[key(site)]||[];if(options.length)$('estimate-plug').value=String(options[0][0]);setStationPower();const price=sitePrice(site);$('estimate-price').value=price?price[0]:'';$('estimate-price-source').textContent=price?(price[2]==='community'?'Tarif utilisateur validé par le groupe, observé le ':price[2]==='network'?'Référence de paiement direct du réseau consultée le ':'Tarif opérateur déclaré le ')+price[1]+' ; vérifiez le prix et les frais actuels.':'Tarif inconnu : saisissez celui de votre offre pour obtenir un coût.';}
    $('estimate-result').hidden=true;if(!site){$('estimate-price').value='';$('estimate-price-source').textContent='Renseignez le tarif applicable à votre offre.';}$('estimate-fixed').value=0;$('estimate-minute').value=0;$('estimate-dialog').showModal();
