    try{const lookup=name=>fetchJSON('https://geo.api.gouv.fr/communes?nom='+encodeURIComponent(name)+'&fields=nom,code,codeDepartement,centre&boost=population&limit=5');const [a,b]=await Promise.all([lookup(from),lookup(to)]);if(generation!==routeRevision)return;routeChoices={from:a.filter(c=>c.centre?.coordinates),to:b.filter(c=>c.centre?.coordinates)};if(!routeChoices.from.length||!routeChoices.to.length)throw Error('Commune introuvable. Précisez les noms.');for(const k of ['from','to'])$('route-'+k+'-choice').innerHTML=routeChoices[k].map((c,i)=>'<option value="'+i+'">'+esc(c.nom+' ('+c.codeDepartement+')')+'</option>').join('');$('route-choices').hidden=false;$('route-status').textContent='Vérifiez les communes proposées, puis calculez le trajet.';}catch(e){$('route-status').textContent=e.message;}finally{$('route-cities').disabled=false;}
